// Page glue: read the three fields, hand them to splitBill, show the result.
// All math lives in src/split.js (served at /split.js) — none here.
import { splitBill } from '/split.js';

const FIELD_IDS = ['bill', 'tipPercent', 'people'];
const OUTPUT_KEYS = ['tip', 'total', 'perPerson'];

const form = document.getElementById('split-form');
const result = document.getElementById('result');
const rows = result.querySelector('.result-rows');
const message = result.querySelector('.message');
const inputs = Object.fromEntries(FIELD_IDS.map((id) => [id, document.getElementById(id)]));
const outputs = Object.fromEntries(OUTPUT_KEYS.map((id) => [id, document.getElementById(id)]));

const money = new Intl.NumberFormat(undefined, {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

// Fields the user has typed in. An untouched field isn't flagged red on load.
const touched = new Set();

function render() {
  const values = Object.fromEntries(FIELD_IDS.map((id) => [id, inputs[id].value]));
  const split = splitBill(values);

  for (const id of FIELD_IDS) {
    const isBad = !split.ok && split.field === id && touched.has(id);
    inputs[id].classList.toggle('invalid', isBad);
    inputs[id].setAttribute('aria-invalid', String(isBad));
  }

  if (split.ok) {
    for (const key of OUTPUT_KEYS) outputs[key].textContent = money.format(split[key]);
    rows.hidden = false;
    message.hidden = true;
    message.textContent = '';
  } else {
    rows.hidden = true;
    message.hidden = false;
    message.textContent = split.message;
  }
}

form.addEventListener('input', (event) => {
  touched.add(event.target.id);
  render();
});
// Enter in a field shouldn't reload the page; results are already live.
form.addEventListener('submit', (event) => event.preventDefault());

render();

