/**
 * Tiny static server, Node built-ins only.
 *
 *   GET /           → public/index.html
 *   GET /<file>     → public/<file>
 *   GET /split.js   → src/split.js (the shared split math, imported by the page)
 *
 * Run: `node server.js` (PORT env var, default 3000).
 */
import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('.', import.meta.url));
const PUBLIC_DIR = join(ROOT, 'public');

/** URL paths served from outside public/. Keep this list tiny and explicit. */
const ALIASES = {
  '/split.js': join(ROOT, 'src', 'split.js'),
};

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.png': 'image/png',
};

/** Map a request URL path to a file on disk, or null if it isn't servable. */
function resolveFile(urlPath) {
  let path;
  try {
    path = decodeURIComponent(urlPath);
  } catch {
    return null;
  }
  if (path in ALIASES) return ALIASES[path];
  if (path.endsWith('/')) path += 'index.html';

  const file = normalize(join(PUBLIC_DIR, path));
  if (!file.startsWith(PUBLIC_DIR + sep)) return null; // traversal attempt
  return file;
}

async function handle(req, res) {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.writeHead(405, { Allow: 'GET, HEAD', 'Content-Type': 'text/plain' });
    return res.end('Method not allowed');
  }

  const { pathname } = new URL(req.url, 'http://localhost');
  const file = resolveFile(pathname);
  const type = file && TYPES[extname(file)];
  if (!type) return notFound(res);

  let body;
  try {
    body = await readFile(file);
  } catch {
    return notFound(res);
  }
  res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-cache' });
  res.end(req.method === 'HEAD' ? undefined : body);
}

function notFound(res) {
  res.writeHead(404, { 'Content-Type': 'text/plain' });
  res.end('Not found');
}

/** Create (but don't start) the server — tests listen on a random port. */
export function createServer() {
  return http.createServer((req, res) => {
    handle(req, res).catch(() => {
      if (!res.headersSent) res.writeHead(500, { 'Content-Type': 'text/plain' });
      res.end('Server error');
    });
  });
}

// Start only when run directly (`node server.js`), not when imported by tests.
if (process.argv[1] && fileURLToPath(import.meta.url) === normalize(process.argv[1])) {
  const port = Number(process.env.PORT) || 3000;
  createServer().listen(port, () => {
    console.log(`Tip Splitter running at http://localhost:${port}`);
  });
}

