import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from './server.js';

let server;
let base;

before(async () => {
  server = createServer();
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
});

after(() => new Promise((resolve) => server.close(resolve)));

// Every file the page needs to load, with the content type the browser expects.
// A wrong type breaks the page silently (e.g. module scripts refuse non-JS types).
const PAGE_FILES = [
  { path: '/', type: /^text\/html/, body: /<script type="module" src="\/app\.js">/ },
  { path: '/app.js', type: /^text\/javascript/, body: /from '\/split\.js'/ },
  { path: '/styles.css', type: /^text\/css/, body: /\{/ },
  { path: '/split.js', type: /^text\/javascript/, body: /export function splitBill/ },
];

for (const { path, type, body } of PAGE_FILES) {
  test(`GET ${path} returns 200 with the right content type`, async () => {
    const res = await fetch(`${base}${path}`);
    assert.equal(res.status, 200);
    assert.match(res.headers.get('content-type'), type);
    assert.match(await res.text(), body);
  });
}

test('every asset index.html links to is served', async () => {
  const html = await (await fetch(`${base}/`)).text();
  const refs = [...html.matchAll(/(?:src|href)="(\/[^"]*)"/g)].map((m) => m[1]);
  assert.ok(refs.length > 0, 'index.html links no local assets');
  for (const ref of refs) {
    const res = await fetch(`${base}${ref}`);
    assert.equal(res.status, 200, ref);
  }
});

test('unknown path is 404', async () => {
  const res = await fetch(`${base}/nope.txt`);
  assert.equal(res.status, 404);
});

test('path traversal cannot escape public/', async () => {
  for (const path of ['/../package.json', '/%2e%2e/package.json', '/..%2fpackage.json']) {
    const res = await fetch(`${base}${path}`);
    assert.equal(res.status, 404, path);
    assert.doesNotMatch(await res.text(), /tip-splitter-2/, path);
  }
});

test('non-GET methods are rejected', async () => {
  const res = await fetch(`${base}/`, { method: 'POST' });
  assert.equal(res.status, 405);
});

