// Runs the real public/app.js against a tiny fake DOM (no dependencies) to
// check the page glue: live updates on input and friendly messages on bad input.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';

const html = await readFile(new URL('./index.html', import.meta.url), 'utf8');

/** Minimal element: just what app.js touches. */
function fakeElement(id, value = '') {
  const classes = new Set();
  const listeners = {};
  return {
    id,
    value,
    hidden: false,
    textContent: '',
    attrs: {},
    classList: {
      toggle: (name, on) => (on ? classes.add(name) : classes.delete(name)),
      contains: (name) => classes.has(name),
    },
    setAttribute(name, v) { this.attrs[name] = v; },
    addEventListener: (type, fn) => { listeners[type] = fn; },
    dispatch: (type, event) => listeners[type]?.(event),
  };
}

/** Value attribute from index.html, so the fake starts like the real page. */
function initialValue(id) {
  const tag = html.match(new RegExp(`<input[^>]*id="${id}"[^>]*>`));
  assert.ok(tag, `index.html has no input #${id}`);
  return tag[0].match(/value="([^"]*)"/)?.[1] ?? '';
}

async function loadPage() {
  const ids = ['split-form', 'result', 'bill', 'tipPercent', 'people', 'tip', 'total', 'perPerson'];
  for (const id of ids) assert.match(html, new RegExp(`id="${id}"`), `index.html is missing #${id}`);

  const els = {};
  for (const id of ids) els[id] = fakeElement(id, ['bill', 'tipPercent', 'people'].includes(id) ? initialValue(id) : '');
  els.rows = fakeElement('rows');
  els.message = fakeElement('message');
  els.result.querySelector = (sel) => ({ '.result-rows': els.rows, '.message': els.message })[sel];
  globalThis.document = { getElementById: (id) => els[id] ?? null };

  // Load app.js as-is, pointing its '/split.js' import at the real shared module.
  const splitUrl = new URL('../src/split.js', import.meta.url).href;
  const src = (await readFile(new URL('./app.js', import.meta.url), 'utf8')).replace("'/split.js'", `'${splitUrl}'`);
  assert.notEqual(src.indexOf(splitUrl), -1, 'app.js should import /split.js');
  await import(`data:text/javascript,${encodeURIComponent(src)}#${Math.random()}`);

  const type = (id, value) => {
